// 1. Obtenemos los 10 clientes del primer nodo
let clientesItems;
try {
  clientesItems = $('Code').all();
} catch (e) {
  try {
    clientesItems = $('Código en JavaScript').all();
  } catch (e2) {
    clientesItems = $input.all();
  }
}

// 2. Obtenemos el texto CSV de las inversiones
const csvTexto = $input.first().json.data || "";
const lineas = csvTexto.split('\n').slice(1);

// 3. Generamos la recomendación para cada uno de los 10 clientes
return clientesItems.map(item => {
  const cliente = item.json;
  const perfilCliente = (cliente.Perfil || cliente.perfil || "").toLowerCase();

  const inversiones = [];
  for (const linea of lineas) {
    const partes = linea.split(',');
    if (partes.length >= 4) {
      const perfil = partes[0].trim().toLowerCase();
      const produto = partes[1].trim();
      const minimo = partes[2].trim();
      const rentabilidade = partes[3].trim();

      if (perfil === perfilCliente) {
        inversiones.push(`${produto} (Mín: R$ ${minimo}, Rentabilidad: ${rentabilidade})`);
      }
    }
  }

  const recomendacion = `Hola ${cliente.Nome || cliente.nome},

Hemos analizado tu perfil de inversionista: ${cliente.Perfil || cliente.perfil}.
Tu saldo actual disponible es: ${cliente.saldo || cliente.Saldo}.

Opciones recomendadas para tu perfil:
- ${inversiones.join('\n- ')}

¡Éxito en tus inversiones!`;

  return {
    json: {
      ...cliente,
      recomendacion: recomendacion
    }
  };
});
